<div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Institución</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($instituciones as $i):?><tr><td><strong><?=$esc($i['nombre'])?></strong><div class="small text-muted"><?=$esc($i['correo']?:$i['telefono'])?></div></td><td><span class="badge bg-<?=(int)$i['estado']===1?'success':'secondary'?>"><?=(int)$i['estado']===1?'Activa':'Inactiva'?></span></td><td><?php if($puedeGestionar):?><button type="button" class="btn btn-sm btn-warning" onclick='editarInstitucion(<?=json_encode($i,JSON_HEX_APOS|JSON_HEX_QUOT)?>)'>Editar</button><form method="POST" action="<?=Config::url('interbibliotecario/institucion/estado')?>" class="d-inline"><input type="hidden" name="id_institucion" value="<?=(int)$i['id_institucion']?>"><input type="hidden" name="estado" value="<?=(int)$i['estado']===1?0:1?>"><button class="btn btn-sm btn-outline-dark"><?=(int)$i['estado']===1?'Desactivar':'Activar'?></button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div>
