<?php if($puedeGestionar):?><form method="POST" action="<?=Config::url('interbibliotecario/libro/guardar')?>" class="row g-2 p-3 border-bottom"><input type="hidden" name="id_libro_externo" id="ext_id" value="0"><div class="col-md-4"><select required class="form-select" name="id_institucion" id="ext_institucion"><option value="">Institución</option><?php foreach($instituciones as $i):?><option value="<?=(int)$i['id_institucion']?>"><?=$esc($i['nombre'])?></option><?php endforeach;?></select></div><div class="col-md-4"><input required class="form-control" name="titulo" id="ext_titulo" placeholder="Título"></div><div class="col-md-4"><input required class="form-control" name="autor" id="ext_autor" placeholder="Autor"></div><div class="col-md-3"><input class="form-control" name="isbn" id="ext_isbn" placeholder="ISBN"></div><div class="col-md-5"><input type="url" class="form-control" name="url_catalogo" id="ext_url" placeholder="Enlace del catálogo"></div><div class="col-md-4 d-grid"><button class="btn btn-primary">Guardar libro</button></div><div class="col-12"><textarea class="form-control" name="descripcion" id="ext_descripcion" rows="2" placeholder="Descripción"></textarea></div></form><?php endif;?>
