</main></div></div>
<script>
function editarInstitucion(i){for(const[k,v]of Object.entries({inst_id:i.id_institucion,inst_nombre:i.nombre,inst_direccion:i.direccion,inst_telefono:i.telefono,inst_correo:i.correo,inst_web:i.sitio_web})){const e=document.getElementById(k);if(e)e.value=v||'';}document.getElementById('inst_nombre').scrollIntoView({behavior:'smooth',block:'center'});}
function editarLibroExterno(l){for(const[k,v]of Object.entries({ext_id:l.id_libro_externo,ext_institucion:l.id_institucion,ext_titulo:l.titulo,ext_autor:l.autor,ext_isbn:l.isbn,ext_url:l.url_catalogo,ext_descripcion:l.descripcion})){const e=document.getElementById(k);if(e)e.value=v||'';}document.getElementById('ext_titulo').scrollIntoView({behavior:'smooth',block:'center'});}
</script>
